std::istream_iterator<int> data_it(std::cin);
std::istream_iterator<int> eos_it; // Default constructed sentinel

// Sentinel comparison defines end of sequence
if (data_it != eos_it) {
    int current_val = *data_it; // Reads current element
    ++data_it;                  // Advances iterator (triggers next read)
}

// Comparison determines loop termination
bool stream_exhausted = (data_it == eos_it);

// Note: If comparison fails (data_it == eos_it),
// data_it is invalid for dereference.
